{
  title: 'Directives/Button',
  component: NovaButtonDirective,
  tags: ['autodocs'],
  parameters: {
    docs: {
      description: {
        component: `
# NovaButton Directive

A directive that applies button styling to native button elements.

## Usage

\`\`\`html
<button novaButton variant="primary" size="medium">
  Click me
</button>
\`\`\`

## Variants

- **primary**: Primary action button
- **secondary**: Secondary action button
- **danger**: Destructive action button
- **ghost**: Minimal button style
- **outline**: Outlined button style
- **link**: Link-style button

## Sizes

- **small**: Compact button for tight spaces
- **medium**: Standard button size (default)
- **large**: Prominent button for primary actions
        `,
      },
    },
  },
  argTypes: {
    variant: {
      control: 'select',
      options: ['primary', 'secondary', 'danger', 'ghost', 'outline', 'link'],
      description: 'Button visual variant',
    },
    size: {
      control: 'select',
      options: ['small', 'medium', 'large'],
      description: 'Button size',
    },
    disabled: {
      control: 'boolean',
      description: 'Whether the button is disabled',
    },
    fullWidth: {
      control: 'boolean',
      description: 'Whether the button should take full width',
    },
  },
  render: (args) => ({
    props: args,
    template: `
      <button novaButton [variant]="variant" [size]="size" [disabled]="disabled" [fullWidth]="fullWidth">
        Button Text
      </button>
    `,
  }),
}

{
  parameters: {
    a11y: {
      disable: false,
    },
    controls: {
      matchers: {
        color: /(background|color)$/i,
        date: /Date$/i,
      },
    },
    backgrounds: {
      disabled: true,
    },
    layout: 'padded',
  },
  globalTypes: {
    theme: {
      name: 'Theme',
      description: 'Global theme for components',
      defaultValue: 'light',
      toolbar: {
        icon: 'circle',
        items: [
          { value: 'light', icon: 'sun', title: 'Light' },
          { value: 'dark', icon: 'moon', title: 'Dark' },
          { value: 'system', icon: 'browser', title: 'System' },
        ],
        showName: true,
      },
    },
  },
  decorators: [
    ((story, context) => {
      const { theme } = context.globals;
      const root = document.documentElement;
      const isDark =
        theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);
      root.classList.toggle('dark', isDark);
      return story();
    }) as Decorator,
  ],
}

